  ('Mathematics', 'Edexcel', 'alevel', 'P1', 'Algebraic Expressions', 'Write 1/√x as a power of x.', 'x^(−1/2).', 16),
  ('Mathematics', 'Edexcel', 'alevel', 'P1', 'Algebraic Expressions', 'Evaluate 27^(1/3).', '3.', 17),
  ('Mathematics', 'Edexcel', 'alevel', 'P1', 'Algebraic Expressions', 'Evaluate 4^(−1/2).', '1/2.', 18),
  ('Mathematics', 'Edexcel', 'alevel', 'P1', 'Algebraic Expressions', 'Evaluate (9/4)^(3/2).', '(3/2)³ = 27/8.', 19),
  ('Mathematics', 'Edexcel', 'alevel', 'P1', 'Algebraic Expressions', 'Expand and simplify (x + 3)(x − 5).', 'x² − 2x − 15.', 20),
