WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What is a conjecture?', 'A statement believed to be true but not yet proved.', 1),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What does "if and only if" require you to prove?', 'Both directions: P ⇒ Q and Q ⇒ P.', 2),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove that the sum of two odd numbers is even.', 'Let the odd numbers be 2m + 1 and 2n + 1. Their sum is 2m + 2n + 2 = 2(m + n + 1), which is even.', 3),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How do you represent an even and an odd integer algebraically?', 'Even: 2n. Odd: 2n + 1 (or 2n − 1), where n is an integer.', 4),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How do you represent consecutive integers?', 'n, n + 1, n + 2, … where n is an integer.', 5),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove that the square of any odd number is odd.', '(2n + 1)² = 4n² + 4n + 1 = 2(2n² + 2n) + 1, which is odd.', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove that n³ − n is always divisible by 6.', 'n³ − n = (n − 1)n(n + 1), the product of three consecutive integers. One is a multiple of 3 and at least one is even, so the product is divisible by 6.', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What is the first step in a proof by contradiction?', 'Assume the negation of the statement you want to prove.', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How do you prove there is no largest even number?', 'Assume N is the largest even number. Then N + 2 is even and larger, a contradiction.', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'When is proof by exhaustion practical?', 'When there is a small finite number of cases to check, e.g. all integers from 1 to 10, or cases such as n odd and n even.', 10),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What does ∴ mean in a proof?', '"Therefore".', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What does the symbol ∈ mean?', '"Is an element of", e.g. n ∈ ℤ means n is an integer.', 12),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What do ℕ, ℤ, ℚ and ℝ represent?', 'Natural numbers, integers, rational numbers and real numbers respectively.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Why is a single example not a proof of a general statement?', 'It only shows the statement holds in that case; a proof must cover every case.', 14),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Simplify √12 + √27.', '2√3 + 3√3 = 5√3.', 1),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Rationalise 1/(√3 − 1).', 'Multiply top and bottom by (√3 + 1): (√3 + 1)/(3 − 1) = (√3 + 1)/2.', 2),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Evaluate 8^(2/3).', '(∛8)² = 2² = 4.', 3),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Evaluate 16^(−3/4).', '1/(⁴√16)³ = 1/2³ = 1/8.', 4),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'What are the roots of ax² + bx + c = 0 given by the quadratic formula?', 'x = (−b ± √(b² − 4ac)) / 2a.', 5),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'What is the vertex of y = (x − p)² + q?', '(p, q); it is a minimum point.', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Complete the square for 2x² + 12x + 5.', '2(x² + 6x) + 5 = 2(x + 3)² − 18 + 5 = 2(x + 3)² − 13.', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Solve x² − 5x + 6 = 0.', '(x − 2)(x − 3) = 0, so x = 2 or x = 3.', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'What is a quadratic in disguise?', 'An equation such as x⁴ − 5x² + 4 = 0 that becomes quadratic with a substitution (u = x²).', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'How do you represent an inequality on a number line?', 'Use an open circle for strict inequalities (< or >) and a filled circle for ≤ or ≥.', 10),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'Express (3x + 1)/((x − 1)(x + 2)) in partial fractions.', 'A/(x − 1) + B/(x + 2). 3x + 1 = A(x + 2) + B(x − 1). x = 1 gives A = 4/3; x = −2 gives B = 5/3.', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'What does y ∝ 1/x² mean?', 'y = k/x² for some constant k (inverse square proportion).', 12),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'What is the product of the roots of ax² + bx + c = 0?', 'c/a.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.2', 'Algebra', 'What is the sum of the roots of ax² + bx + c = 0?', '−b/a.', 14),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'Divide x³ − 2x² − 5x + 6 by (x − 1).', 'x³ − 2x² − 5x + 6 = (x − 1)(x² − x − 6) = (x − 1)(x − 3)(x + 2).', 1),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is a many-to-one function?', 'A function where more than one input gives the same output, e.g. f(x) = x².', 2),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is a one-to-one function?', 'Each output comes from exactly one input; only one-to-one functions have inverses.', 3),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is a mapping that is not a function?', 'One where an input maps to more than one output, e.g. y = ±√x.', 4),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'Find the inverse of f(x) = (2x + 1)/3.', 'Let y = (2x + 1)/3, so x = (3y − 1)/2. f⁻¹(x) = (3x − 1)/2.', 5),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is the domain of f⁻¹?', 'The range of f.', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'If f(x) = x² and g(x) = x + 3, find fg(x) and gf(x).', 'fg(x) = (x + 3)²; gf(x) = x² + 3.', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is the range of f(x) = x² + 4?', 'f(x) ≥ 4.', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is the range of f(x) = eˣ?', 'f(x) > 0.', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is the domain of f(x) = ln x?', 'x > 0.', 10),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'Solve |2x − 1| = 5.', '2x − 1 = 5 or 2x − 1 = −5, so x = 3 or x = −2.', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'Solve |x − 2| < 3.', '−3 < x − 2 < 3, so −1 < x < 5.', 12),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is an odd function?', 'f(−x) = −f(x); the graph has rotational symmetry of order 2 about the origin, e.g. sin x.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.3', 'Functions', 'What is an even function?', 'f(−x) = f(x); the graph is symmetric about the y-axis, e.g. cos x.', 14),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'Describe the transformation from y = x² to y = (x − 3)² + 2.', 'A translation by the vector (3, 2).', 1),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'Describe the transformation from y = sin x to y = 3 sin x.', 'A stretch parallel to the y-axis, scale factor 3.', 2),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'Describe the transformation from y = cos x to y = cos 2x.', 'A stretch parallel to the x-axis, scale factor 1/2.', 3),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'Describe the transformation y = f(x) to y = −f(x).', 'A reflection in the x-axis.', 4),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'Describe the transformation y = f(x) to y = f(−x).', 'A reflection in the y-axis.', 5),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What is the shape of y = x³?', 'An S-shaped curve through the origin, increasing, with a point of inflection at the origin.', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What is the shape of y = 1/x?', 'A hyperbola in the first and third quadrants, with asymptotes x = 0 and y = 0.', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What is the shape of y = 1/x²?', 'Two branches, both above the x-axis, with asymptotes x = 0 and y = 0.', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'Where does y = (x − 1)(x + 2)² touch the x-axis?', 'It crosses at x = 1 and touches (a repeated root) at x = −2.', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What is the y-intercept of y = (x − 1)(x + 2)(x − 3)?', 'Substitute x = 0: (−1)(2)(−3) = 6.', 10),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'How do you find where two graphs intersect?', 'Set the equations equal and solve.', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What happens to y = ax³ + … as x → ∞ if a > 0?', 'y → ∞.', 12),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What are the asymptotes of y = 1/(x − 2) + 3?', 'x = 2 and y = 3.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.4', 'Graphs', 'What does a stationary point of inflection look like?', 'The gradient is zero, but the curve doesn''t change from increasing to decreasing (or vice versa), e.g. y = x³ at the origin.', 14),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'Find the equation of the line through (1, 2) with gradient 3.', 'y − 2 = 3(x − 1), so y = 3x − 1.', 1),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What is the gradient of the line 2x + 3y = 6?', 'Rearrange to y = −2x/3 + 2, so gradient = −2/3.', 2),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'Find the equation of the perpendicular bisector of A(0, 0) and B(4, 2).', 'Midpoint (2, 1); gradient AB = 1/2, so perpendicular gradient = −2. y − 1 = −2(x − 2), so y = −2x + 5.', 3),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What is the distance between (1, 2) and (4, 6)?', '√((4 − 1)² + (6 − 2)²) = √(9 + 16) = 5.', 4),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'Find the centre and radius of x² + y² − 4x + 6y − 12 = 0.', '(x − 2)² + (y + 3)² = 25: centre (2, −3), radius 5.', 5),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What does the angle in a semicircle theorem state?', 'The angle subtended at the circumference by a diameter is a right angle.', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What does the perpendicular from the centre to a chord do?', 'It bisects the chord.', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What is the relationship between a tangent and a radius?', 'A tangent is perpendicular to the radius at the point of contact.', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'How do you find the equation of a circle through three points?', 'Find the perpendicular bisectors of two chords; they intersect at the centre. Then find the radius.', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'Convert x = t², y = 2t into Cartesian form.', 't = y/2, so x = y²/4, i.e. y² = 4x.', 10),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'Find dy/dx for x = t², y = t³.', 'dy/dx = (3t²)/(2t) = 3t/2.', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What is the parametric form of the circle (x − a)² + (y − b)² = r²?', 'x = a + r cos θ, y = b + r sin θ.', 12),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'How do you find where a parametric curve meets the x-axis?', 'Set y = 0, solve for t, then substitute into x.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.5', 'Coordinate Geometry', 'What does it mean if a line meets a circle at exactly one point?', 'The line is a tangent to the circle (the discriminant is zero).', 14),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'Find the 10th term of the arithmetic sequence 3, 7, 11, …', 'a = 3, d = 4: u₁₀ = 3 + 9 × 4 = 39.', 1),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'Find the sum of the first 20 terms of 3, 7, 11, …', 'S₂₀ = 20/2 × (2 × 3 + 19 × 4) = 10 × 82 = 820.', 2),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'Find the sum to infinity of 8 + 4 + 2 + …', 'a = 8, r = 1/2: S∞ = 8/(1 − 1/2) = 16.', 3),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is a periodic sequence?', 'A sequence that repeats after a fixed number of terms, e.g. 1, −1, 1, −1, …', 4),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is an increasing sequence?', 'Each term is larger than the previous one: uₙ₊₁ > uₙ for all n.', 5),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is a divergent sequence?', 'A sequence that doesn''t tend to a finite limit.', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is sigma notation?', 'A shorthand for sums: Σ from r=1 to n of f(r) means f(1) + f(2) + … + f(n).', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is ⁿCᵣ?', 'The number of ways of choosing r items from n: n!/(r!(n − r)!).', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'Find the coefficient of x³ in (2 + x)⁵.', '⁵C₃ × 2² × x³ = 10 × 4 = 40.', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'Expand (1 − x)⁻¹ up to x³.', '1 + x + x² + x³, valid for |x| < 1.', 10),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'Expand (1 + 2x)⁻² up to x².', '1 − 4x + 12x², valid for |x| < 1/2.', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is Pascal''s triangle used for?', 'To find binomial coefficients for small positive integer powers.', 12),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'What is n! ?', 'n × (n − 1) × … × 2 × 1, with 0! = 1.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.6', 'Sequences & Series', 'How do you find the number of terms in an arithmetic sequence?', 'Use uₙ = a + (n − 1)d, set it equal to the last term and solve for n.', 14),
