  ('Mathematics', 'OCR B', 'alevel', '1.7', 'Trigonometry', 'What is the period of y = sin x and y = tan x?', 'sin x has period 2π (360°); tan x has period π (180°).', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.7', 'Trigonometry', 'What is the identity linking tan, sin and cos?', 'tan θ = sin θ/cos θ.', 8),
