  ('Mathematics', 'OCR B', 'alevel', '1.7', 'Trigonometry', 'Solve sin x = 0.5 for 0 ≤ x < 2π.', 'x = π/6 or x = 5π/6.', 11),
  ('Mathematics', 'OCR B', 'alevel', '1.7', 'Trigonometry', 'What are the principal value ranges of arcsin, arccos and arctan?', 'arcsin: −π/2 to π/2; arccos: 0 to π; arctan: −π/2 to π/2 (exclusive).', 12),
