  ('Mathematics', 'OCR B', 'alevel', '1.8', 'Exponentials & Logarithms', 'If y = axⁿ, what does a log–log graph give?', 'log y = log a + n log x: a straight line with gradient n and intercept log a.', 13),
  ('Mathematics', 'OCR B', 'alevel', '1.8', 'Exponentials & Logarithms', 'If y = abˣ, what does plotting log y against x give?', 'log y = log a + x log b: a straight line with gradient log b and intercept log a.', 14),
