  ('Mathematics', 'OCR B', 'alevel', '1.11', 'Differential Equations', 'What is the general solution of dT/dt = −k(T − T₀)?', 'T = T₀ + Ae^(−kt).', 6),
  ('Mathematics', 'OCR B', 'alevel', '1.11', 'Differential Equations', 'What does the constant k represent in dP/dt = kP?', 'The growth rate constant (k > 0 for growth, k < 0 for decay).', 7),
  ('Mathematics', 'OCR B', 'alevel', '1.11', 'Differential Equations', 'Solve dy/dx = x/y.', '∫y dy = ∫x dx, so y²/2 = x²/2 + c, giving y² = x² + C.', 8),
  ('Mathematics', 'OCR B', 'alevel', '1.11', 'Differential Equations', 'What does a slope field (direction field) show?', 'Short line segments showing the gradient dy/dx at points in the plane, indicating the shape of solution curves.', 9),
  ('Mathematics', 'OCR B', 'alevel', '1.11', 'Differential Equations', 'What is an initial condition?', 'A known value of the function at a particular point, used to find the constant of integration.', 10),
